mapper.select:
SELECT TOP (#{limit}) id, request_id, interface_code, organization_code, source_record_id, source_system_code AS caller_system_code, target_system_code, exchange_result AS result, result_code AS target_result_code, result_message, duration_ms, request_summary, communication_error_summary, received_at, processed_at FROM exch_exchange_record WHERE organization_code = #{organizationCode}
AND received_at >= #{receivedFrom}
AND received_at <= #{receivedTo}
AND interface_code = #{interfaceCode}
AND source_record_id = #{sourceRecordId}
AND request_id = #{requestId}
AND exchange_result = #{result}
ORDER BY received_at DESC, id DESC
